query:
SELECT COUNT(*) as count, MIN(createdAt) as min_date, MAX(createdAt) as max_date 
FROM inventory 
WHERE createdAt >= '2026-05-01 00:00:00' AND createdAt < '2026-06-01 00:00:00';

